.carousel-header-text p {
  font-size: 17px;
  color: #6e6e73;
  font-weight: 300;
}
.carousel-header-text .promo {
  font-size: 13px;
  color: #0066cc;
  margin-top: 6px;
}
.carousel-nav-btns {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}
.carousel-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #f5f5f7;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background .15s, opacity .15s;
  color: #1d1d1f;
}
.carousel-btn:hover { background: #e8e8ed; }
.carousel-btn:disabled { opacity: .3; cursor: default; }
.carousel-btn svg { pointer-events: none; }

.carousel-track-wrap {
  position: relative;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 52px;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 14px;
  transition: transform .4s cubic-bezier(.25,.46,.45,.94);
