.product-card-img svg { max-width: 120px; max-height: 120px; }
.product-card-name {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.product-card-tag {
  font-size: 13px;
  color: #6e6e73;
  margin-bottom: 12px;
  line-height: 1.4;
  flex: 1;
}
.product-card-price {
  font-size: 14px;
  font-weight: 500;
  color: #1d1d1f;
  margin-bottom: 2px;
}
.product-card-monthly {
  font-size: 12px;
  color: #6e6e73;
  margin-bottom: 14px;
}
.product-card-links {
  display: flex;
  gap: 14px;
  font-size: 13px;
}
.product-card-links a {
  color: #0066cc;
  text-decoration: none;
}
.product-card-links a:hover { text-decoration: underline; }

/* ── Help card ── */
.help-card {
  flex: 0 0 220px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.help-card-icon { font-size: 32px; line-height: 1; }
.help-card-name { font-size: 17px; font-weight: 600; }
.help-card-desc { font-size: 14px; color: #6e6e73; line-height: 1.5; }
.help-card-link { font-size: 14px; color: #0066cc; margin-top: auto; }
.help-card-link:hover { text-decoration: underline; }

/* ── Difference card ── */
.diff-card {
  flex: 0 0 220px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.diff-card-icon { font-size: 28px; }
.diff-card-name { font-size: 17px; font-weight: 600; }
.diff-card-desc { font-size: 14px; color: #6e6e73; line-height: 1.5; }

/* ── Accessory card ── */
.acc-card {
  flex: 0 0 200px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 22px 18px 18px;
  display: flex;
  flex-direction: column;
}
.acc-card-img {
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  font-size: 60px;
}
.acc-card-name {
  font-size: 14px;
  font-weight: 500;
  color: #1d1d1f;
  margin-bottom: 4px;
  line-height: 1.3;
  flex: 1;
}
.acc-card-price {
  font-size: 14px;
  color: #1d1d1f;
  font-weight: 400;
  margin-bottom: 8px;
}
.acc-card-link { font-size: 13px; color: #0066cc; }
.acc-card-link:hover { text-decoration: underline; }

/* ── Audio card ── */
.audio-card {
  flex: 0 0 220px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 24px 20px 20px;
  display: flex;
  flex-direction: column;
}
.audio-card-img {
  height: 150px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
  font-size: 64px;
}
.audio-card-name {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: 4px;
  flex: 1;
}
.audio-card-engrave {
  font-size: 12px;
  color: #6e6e73;
  margin-bottom: 6px;
}
.audio-card-price {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 12px;
}
.audio-card-links { display: flex; gap: 14px; font-size: 13px; }
.audio-card-links a { color: #0066cc; }
.audio-card-links a:hover { text-decoration: underline; }

/* ── Savings card ── */
.savings-card {
  flex: 0 0 260px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.savings-card.dark {
  background: #1d1d1f;
  color: #f5f5f7;
}
.savings-card-icon { font-size: 36px; }
.savings-card-title { font-size: 19px; font-weight: 700; }
.savings-card-desc { font-size: 14px; color: #6e6e73; line-height: 1.5; }
.savings-card.dark .savings-card-desc { color: #a1a1a6; }
.savings-card-link { font-size: 14px; color: #0066cc; margin-top: auto; }
.savings-card-link:hover { text-decoration: underline; }

/* ── Model card ── */
.model-card {
  flex: 0 0 240px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 22px 22px;
  display: flex;
  flex-direction: column;
  position: relative;
}
.model-card-badge {
  position: absolute;
  top: 14px;
  left: 16px;
  background: #0066cc;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .5px;
  padding: 3px 8px;
  border-radius: 20px;
  text-transform: uppercase;
}
.model-card-img {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
  font-size: 72px;
}
.model-card-name { font-size: 20px; font-weight: 700; margin-bottom: 6px; }
.model-card-price { font-size: 15px; color: #1d1d1f; font-weight: 500; margin-bottom: 3px; }
.model-card-monthly { font-size: 12px; color: #6e6e73; margin-bottom: 16px; flex: 1; }
.model-card-links { display: flex; gap: 14px; font-size: 13px; }
.model-card-links a { color: #0066cc; }
.model-card-links a:hover { text-decoration: underline; }

/* ── Guide / Ways cards (category pages) ── */
.guide-card {
  flex: 0 0 240px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.guide-card-icon { font-size: 28px; }
.guide-card-title { font-size: 17px; font-weight: 600; }
.guide-card-desc { font-size: 14px; color: #6e6e73; line-height: 1.5; flex: 1; }
.guide-card-link { font-size: 13px; color: #0066cc; margin-top: 8px; }
.guide-card-link:hover { text-decoration: underline; }

/* ── Section nav (category pages) ── */
.section-nav {
  background: rgba(255,255,255,.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid #d2d2d7;
  position: sticky;
  top: 48px;
  z-index: 90;
}
.section-nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  gap: 0;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 0 22px;
}
.section-nav-inner::-webkit-scrollbar { display: none; }
.section-nav-link {
  padding: 14px 18px;
  font-size: 13px;
  color: #6e6e73;
  white-space: nowrap;
  border-bottom: 2px solid transparent;
  transition: color .15s, border-color .15s;
  cursor: pointer;
}
.section-nav-link:hover,
.section-nav-link.active {
  color: #1d1d1f;
  border-bottom-color: #1d1d1f;
}

/* ── Category Hero ── */
.cat-hero {
  text-align: center;
  padding: 70px 20px 60px;
  background: #f5f5f7;
}
.cat-hero-eyebrow {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
  color: #6e6e73;
  margin-bottom: 12px;
}
.cat-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -1.5px;
  margin-bottom: 16px;
}
.cat-hero p {
  font-size: 19px;
  color: #6e6e73;
  max-width: 500px;
  margin: 0 auto 28px;
  line-height: 1.5;
}

/* ── Store Hero ── */
.store-hero {
  text-align: center;
  padding: 70px 20px 60px;
  background: #f5f5f7;
  border-bottom: 1px solid #d2d2d7;
}
.store-hero h1 {
  font-size: 56px;
  font-weight: 700;
  letter-spacing: -1.5px;
  margin-bottom: 16px;
}
.store-hero p {
  font-size: 21px;
  color: #6e6e73;
  margin-bottom: 28px;
}
.store-hero-btns {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}
.btn-primary {
  background: #0066cc;
  color: #fff;
  padding: 12px 24px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  border: none;
  cursor: pointer;
  transition: background .15s;
  text-decoration: none;
  display: inline-block;
}
.btn-primary:hover { background: #0055b3; }
.btn-secondary {
  background: transparent;
  color: #0066cc;
  padding: 10px 22px;
  border-radius: 980px;
  font-size: 15px;
  font-weight: 500;
  border: 1.5px solid #0066cc;
  cursor: pointer;
  transition: background .15s, color .15s;
  text-decoration: none;
  display: inline-block;
}
.btn-secondary:hover { background: #0066cc; color: #fff; }

/* ── Product icon bar ── */
.product-icon-bar {
  padding: 18px 0;
  border-bottom: 1px solid #d2d2d7;
  overflow-x: auto;
  scrollbar-width: none;
}
.product-icon-bar::-webkit-scrollbar { display: none; }
.product-icon-bar-inner {
  display: flex;
  gap: 0;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 22px;
  justify-content: center;
}
.product-icon-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  font-size: 12px;
  color: #1d1d1f;
  text-decoration: none;
  border-radius: 8px;
  transition: background .15s;
  white-space: nowrap;
}
.product-icon-item:hover { background: #f5f5f7; }
.product-icon-item svg, .product-icon-item span.icon { font-size: 24px; line-height: 1; }

/* ── Brand collab ── */
.brand-collab {
  background: linear-gradient(135deg, #0f0f0f 0%, #1a1a2e 50%, #0f0f0f 100%);
  color: #fff;
  text-align: center;
  padding: 70px 20px;
}
.brand-collab h2 {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -.5px;
  margin-bottom: 12px;
}
.brand-collab .sub {
  font-size: 19px;
  color: #a1a1a6;
  margin-bottom: 24px;
}
.brand-collab .desc {
  font-size: 15px;
  color: #8e8e93;
  max-width: 500px;
  margin: 0 auto 28px;
  line-height: 1.5;
}
.collab-icons { font-size: 48px; margin-bottom: 24px; display: flex; gap: 20px; justify-content: center; align-items: center; }

/* ── Quick links ── */
.quick-links-section {
  padding: 40px 20px;
  border-bottom: 1px solid #d2d2d7;
}
.quick-links-inner {
  max-width: 1400px;
  margin: 0 auto;
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  justify-content: center;
}
.quick-link-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #f5f5f7;
  color: #1d1d1f;
  font-size: 14px;
  font-weight: 500;
  padding: 12px 22px;
  border-radius: 980px;
  text-decoration: none;
  border: none;
  transition: background .15s;
}
.quick-link-btn:hover { background: #e8e8ed; }

/* ── Special stores / Savings section ── */
.special-stores-section {
  padding: 52px 0;
  border-bottom: 1px solid #d2d2d7;
}
.special-stores-header {
  max-width: 1400px;
  margin: 0 auto 28px;
  padding: 0 52px;
}
.special-stores-header h2 {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -.5px;
  margin-bottom: 4px;
}
.special-stores-header p {
  font-size: 17px;
  color: #6e6e73;
}
.special-stores-grid {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 52px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 14px;
}
.special-store-card {
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.special-store-card-icon { font-size: 28px; }
.special-store-card-title { font-size: 17px; font-weight: 600; }
.special-store-card-desc { font-size: 14px; color: #6e6e73; line-height: 1.5; flex: 1; }
.special-store-card-link { font-size: 13px; color: #0066cc; margin-top: 8px; }
.special-store-card-link:hover { text-decoration: underline; }

/* ── Setup support ── */
.setup-support-section {
  padding: 52px 20px;
  text-align: center;
  background: #f5f5f7;
  border-bottom: 1px solid #d2d2d7;
}
.setup-support-section h2 {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -.5px;
  margin-bottom: 8px;
}
.setup-support-section p {
  font-size: 17px;
  color: #6e6e73;
  margin-bottom: 24px;
}
.setup-support-section .btns { display: flex; gap: 14px; justify-content: center; flex-wrap: wrap; }

/* ── Footer ── */
.site-footer {
  background: #f5f5f7;
  border-top: 1px solid #d2d2d7;
  padding: 40px 0 20px;
}
.footer-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 22px;
}
.footer-legal {
  padding-bottom: 20px;
  border-bottom: 1px solid #d2d2d7;
  margin-bottom: 28px;
}
.footer-legal p {
  font-size: 12px;
  color: #6e6e73;
  line-height: 1.5;
  margin-bottom: 6px;
}
.footer-legal a { color: #0066cc; }
.footer-legal a:hover { text-decoration: underline; }
.footer-cols {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 28px 20px;
  margin-bottom: 36px;
}
.footer-col-title {
  font-size: 12px;
  font-weight: 600;
  color: #1d1d1f;
  margin-bottom: 12px;
}
.footer-col ul li {
  margin-bottom: 8px;
}
.footer-col ul li a {
  font-size: 12px;
  color: #6e6e73;
  transition: color .15s;
}
.footer-col ul li a:hover { color: #1d1d1f; }
.footer-bottom {
  padding-top: 20px;
  border-top: 1px solid #d2d2d7;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
}
.footer-bottom p { font-size: 12px; color: #6e6e73; }
.footer-bottom-links {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.footer-bottom-links a {
  font-size: 12px;
  color: #6e6e73;
  transition: color .15s;
}
.footer-bottom-links a:hover { color: #1d1d1f; }

/* ── Responsive ── */
@media (max-width: 900px) {
  .nav-links { display: none; }
  .product-grid-inner { grid-template-columns: 1fr; }
  .hero-tile { min-height: 280px; }
  .hero-tile-title { font-size: 22px; }
  .carousel-header { padding: 0 22px; }
  .carousel-track-wrap { padding: 0 22px; }
  .special-stores-header { padding: 0 22px; }
  .special-stores-grid { padding: 0 22px; grid-template-columns: repeat(2, 1fr); }
  .footer-cols { grid-template-columns: repeat(2, 1fr); }

  /* Footer accordion on mobile */
  .footer-col-title {
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: space-between;
    user-select: none;
  }
  .footer-col-title::after {
    content: '+';
    font-size: 16px;
    font-weight: 300;
  }
  .footer-col-title.open::after { content: '−'; }
  .footer-col ul { display: none; }
  .footer-col ul.open { display: block; }
}

@media (max-width: 600px) {
  .cat-hero h1, .store-hero h1 { font-size: 36px; }
  .special-stores-grid { grid-template-columns: 1fr; }
  .quick-links-inner { gap: 8px; }
  .quick-link-btn { font-size: 13px; padding: 10px 16px; }
}

