/* ─────────────────────────────────────────
   Orchard — Shared Styles
   ───────────────────────────────────────── */

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

body {
  font-family: -apple-system, "Helvetica Neue", Arial, sans-serif;
  background: #fff;
  color: #1d1d1f;
  -webkit-font-smoothing: antialiased;
}

a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { font-family: inherit; cursor: pointer; }

/* ── Global Nav ── */
.global-nav {
  background: rgba(255,255,255,.85);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid rgba(0,0,0,.08);
  position: sticky;
  top: 0;
  z-index: 100;
  height: 48px;
}
.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 22px;
}
.nav-logo svg { display: block; }
.nav-links {
  display: flex;
  gap: 28px;
  align-items: center;
}
.nav-links a {
  font-size: 13px;
  color: #1d1d1f;
  opacity: .85;
  transition: opacity .15s;
}
.nav-links a:hover { opacity: 1; }
.nav-actions {
  display: flex;
  gap: 20px;
  align-items: center;
}

/* ── Carousel ── */
.carousel-section {
  padding: 52px 0;
  border-bottom: 1px solid #d2d2d7;
}
.carousel-header {
  max-width: 1400px;
  margin: 0 auto 28px;
  padding: 0 52px;
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}
.carousel-header-text h2 {
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -.5px;
  margin-bottom: 4px;
}
.carousel-header-text p {
  font-size: 17px;
  color: #6e6e73;
  font-weight: 300;
}
.carousel-header-text .promo {
  font-size: 13px;
  color: #0066cc;
  margin-top: 6px;
}
.carousel-nav-btns {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
}
.carousel-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: #f5f5f7;
  border: none;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: background .15s, opacity .15s;
  color: #1d1d1f;
}
.carousel-btn:hover { background: #e8e8ed; }
.carousel-btn:disabled { opacity: .3; cursor: default; }
.carousel-btn svg { pointer-events: none; }

.carousel-track-wrap {
  position: relative;
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 52px;
  overflow: hidden;
}
.carousel-track {
  display: flex;
  gap: 14px;
  transition: transform .4s cubic-bezier(.25,.46,.45,.94);
  will-change: transform;
}

/* ── Product Card ── */
.product-card {
  flex: 0 0 220px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 24px 20px 20px;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}
.product-card-badge {
  position: absolute;
  top: 14px;
  left: 16px;
  background: #0066cc;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .5px;
  padding: 3px 8px;
  border-radius: 20px;
  text-transform: uppercase;
}
.product-card-img {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}
.product-card-img svg { max-width: 120px; max-height: 120px; }
.product-card-name {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: 4px;
}
.product-card-tag {
  font-size: 13px;
  color: #6e6e73;
  margin-bottom: 12px;
  line-height: 1.4;
  flex: 1;
}
.product-card-price {
  font-size: 14px;
  font-weight: 500;
  color: #1d1d1f;
  margin-bottom: 2px;
}
.product-card-monthly {
  font-size: 12px;
  color: #6e6e73;
  margin-bottom: 14px;
}
.product-card-links {
  display: flex;
  gap: 14px;
  font-size: 13px;
}
.product-card-links a {
  color: #0066cc;
  text-decoration: none;
}
.product-card-links a:hover { text-decoration: underline; }

/* ── Help card ── */
.help-card {
  flex: 0 0 220px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.help-card-icon { font-size: 32px; line-height: 1; }
.help-card-name { font-size: 17px; font-weight: 600; }
.help-card-desc { font-size: 14px; color: #6e6e73; line-height: 1.5; }
.help-card-link { font-size: 14px; color: #0066cc; margin-top: auto; }
.help-card-link:hover { text-decoration: underline; }

/* ── Difference card ── */
.diff-card {
  flex: 0 0 220px;
  border-radius: 16px;
  background: #f5f5f7;
  padding: 28px 22px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
